package com.pointverse.app;
import android.test.InstrumentationTestCase;import org.json.*;import java.util.*;import java.io.*;
@SuppressWarnings("deprecation")
public final class ManifestationTest extends InstrumentationTestCase {
 private PointStore store;private String name,id;
 protected void setUp()throws Exception {super.setUp();name="manifest-"+UUID.randomUUID()+".db";store=new PointStore(getInstrumentation().getTargetContext(),name);id=store.createText("原始标题","一段仍需继续发展的想法");}
 protected void tearDown()throws Exception {store.close();getInstrumentation().getTargetContext().deleteDatabase(name);super.tearDown();}
 private JSONObject reply(String text)throws Exception{return new JSONObject().put("model","actual-text-model").put("choices",new JSONArray().put(new JSONObject().put("message",new JSONObject().put("content",text))));}
 public void testTextIsIndependentArtifactAndDoesNotCallImageApi()throws Exception {PointStore.Point source=store.get(id);Manifestation.Result result=new Manifestation((path,method,payload)->{assertEquals("/v1/ai/chat/completions",path);assertEquals(source.context(),payload.getJSONArray("messages").getJSONObject(1).getString("content"));return reply("想法逐渐清晰，仍保留开放的问题。");},"pointverse-cloud").create(source.context());store.saveManifestation(source,result.text,result.model);JSONArray rows=store.rows("manifestations",id);assertEquals(1,rows.length());assertEquals("text",rows.getJSONObject(0).getString("kind"));assertEquals("actual-text-model",rows.getJSONObject(0).getString("model"));assertEquals(source.title,store.get(id).title);assertEquals(source.body,store.get(id).body);assertEquals(0,store.rows("images",id).length());assertTrue(new CloudSync(store).snapshot(store.get(id)).getJSONObject("payload").getJSONArray("manifestations").length()==1);}
 public void testHistorySurvivesTrashRestoreAndIsPurgedWithPoint()throws Exception {PointStore.Point source=store.get(id);store.saveManifestation(source,"版本一","model");store.saveManifestation(source,"版本二","model");assertEquals(2,store.rows("manifestations",id).length());store.trash(id,true);store.trash(id,false);assertEquals(2,store.rows("manifestations",id).length());store.trash(id,true);store.purge(id);assertEquals(0,store.rows("manifestations",id).length());}
 public void testVersionSixUpgradePreservesOriginalAndAddsArtifactTable()throws Exception {store.getWritableDatabase().execSQL("DROP TABLE manifestations");store.getWritableDatabase().setVersion(6);store.close();store=new PointStore(getInstrumentation().getTargetContext(),name);assertEquals("原始标题",store.get(id).title);store.saveManifestation(store.get(id),"迁移后作品","model");assertEquals(1,store.rows("manifestations",id).length());}
 public void testEmptyOrFailedTextIsNeverSavedAsArtifact()throws Exception {try{new Manifestation((p,m,b)->{throw new IOException("failed");},"model").create("想法");fail();}catch(IOException expected){}assertEquals(0,store.rows("manifestations",id).length());try{store.saveManifestation(store.get(id)," ","model");fail();}catch(IOException expected){}}
}
